import React, { useState } from 'react';

interface GalleryItem {
  id: string;
  category?: string;
  title: string;
  description: string;
  image: string;
  link: string;
}

const items: GalleryItem[] = [
  {
    id: '1',
    category: 'News',
    title: 'Introducing the Ciridae',
    description:
      'The AI revolution demands transformation, not optimization-become intelligent or become history.',
    image:
      'https://images.unsplash.com/photo-1677442136019-21780ecad995?auto=format&fit=crop&q=80&w=2560',
    link: '#',
  },
  {
    id: '2',
    title: 'Restoration Rebuttal Automation',
    description:
      'AI automation for insurance claim rebuttals, reducing CEO time investment by 90% per estimate.',
    image:
      'https://images.unsplash.com/photo-1551288049-bebda4e38f71?auto=format&fit=crop&q=80&w=2560',
    link: '#',
  },
  {
    id: '3',
    title: 'The Future of Coding Is Orchestration',
    description:
      'From keystrokes to orchestration: Claude Code transforms engineering workflow with AI-driven code.',
    image:
      'https://images.unsplash.com/photo-1555066931-4365d14bab8c?auto=format&fit=crop&q=80&w=2560',
    link: '#',
  },
];

const StaggeredText = ({ text, isActive }: { text: string; isActive: boolean }) => {
  const words = text.split(' ');
  return (
    <p className="text-white/80 text-[15px] leading-[1.2] tracking-[-0.3px] m-0">
      {words.map((word, i) => (
        <span key={i} className="inline-block relative overflow-hidden" style={{ marginRight: '0.25em' }}>
          <span
            className={`inline-block transition-all duration-500 ease-out ${
              isActive ? 'translate-y-0 opacity-100' : 'translate-y-[10px] opacity-0'
            }`}
            style={{ transitionDelay: `${isActive ? i * 20 : 0}ms` }}
          >
            {word}
          </span>
        </span>
      ))}
    </p>
  );
};

export default function AccordionGallery() {
  const [activeIndex, setActiveIndex] = useState<number>(0);

  return (
    <div className="bg-[#0b0b0b] text-white font-sans w-full overflow-hidden flex justify-center">
      {/* Main Container */}
      <div role="list" className="h-[80vh] min-h-[600px] max-h-[1000px] w-full max-w-[1400px] flex flex-col py-8 px-4 md:px-12">
        {items.map((item, index) => {
          const isActive = activeIndex === index;
          return (
            <div
              key={item.id}
              role="listitem"
              className={`relative flex justify-center items-center py-2 transition-[flex-grow] duration-[800ms] ease-[cubic-bezier(0.25,1,0.5,1)] cursor-pointer group`}
              style={{ 
                flexGrow: isActive ? 1 : 0.35, 
                flexBasis: 0, 
                minHeight: '80px'
              }}
              onMouseEnter={() => setActiveIndex(index)}
              onClick={() => setActiveIndex(index)}
            >
              {/* Left Badge (Desktop) */}
              {item.category && (
                <div
                  className={`hidden lg:block absolute right-[calc(100%+32px)] bottom-8 transition-all duration-700 ease-out ${
                    isActive ? 'opacity-100 translate-x-0' : 'opacity-0 translate-x-4 pointer-events-none'
                  }`}
                >
                  <div className="px-3 py-1.5 rounded-full border border-white/80">
                    <div className="font-mono text-[11px] tracking-[-0.22px] uppercase">
                      {item.category}
                    </div>
                  </div>
                </div>
              )}

              {/* Right Content (Desktop) */}
              <div
                className={`hidden lg:flex w-max max-w-60 absolute flex-col gap-6 bottom-8 transition-all duration-700 delay-100 ease-out ${
                  isActive ? 'left-[calc(100%+32px)] opacity-100' : 'left-[calc(100%+16px)] opacity-0 pointer-events-none'
                }`}
              >
                <div className="font-mono text-[13px] leading-[1.1] tracking-[-0.28px] uppercase">
                  {item.title}
                </div>
                <div className="max-w-[226px]">
                  <StaggeredText text={item.description} isActive={isActive} />
                </div>
              </div>

              {/* Central Image Link */}
              <a
                href={item.link}
                className="h-full w-full max-w-[1000px] aspect-video relative flex overflow-hidden justify-center items-center focus:outline-none focus:ring-2 focus:ring-white/50"
              >
                <img
                  src={item.image}
                  loading="lazy"
                  alt={item.title}
                  className={`w-full h-full object-cover origin-center transition-all duration-[1200ms] ease-out ${
                    isActive ? 'scale-100 opacity-100 grayscale-0' : 'scale-[1.02] opacity-40 grayscale-[50%] group-hover:opacity-70 group-hover:grayscale-[20%]'
                  }`}
                />

                {/* Mobile/Tablet Overlay (shows when absolute side-panels are hidden) */}
                <div className={`lg:hidden absolute inset-0 bg-gradient-to-t from-black/90 via-black/20 to-transparent flex flex-col justify-end p-6 transition-opacity duration-500 ${
                  isActive ? 'opacity-100' : 'opacity-0'
                }`}>
                  {item.category && (
                    <span className="font-mono text-[10px] uppercase border border-white/60 rounded-full px-2 py-0.5 w-max mb-3">
                      {item.category}
                    </span>
                  )}
                  <h3 className="font-mono text-sm uppercase mb-2 leading-tight tracking-tight">{item.title}</h3>
                  <p className="text-white/80 text-xs leading-relaxed max-w-md">
                    {item.description}
                  </p>
                </div>
              </a>
            </div>
          );
        })}
      </div>
    </div>
  );
}
